/**
 * Protocol registry rows (pure data; validated by protocols.ts at load).
 *
 * GENERATED on 2026-10-31 from three inputs, then committed as data:
 * - the hand-written rows of 2026-10-29 (HyperCore, HyperEVM, Elysium
 *   predeploys, the first Elysium protocols);
 * - the Elysium protocol census of 2026-10-31
 *   (elyia-design/research/elysium-protocols.json: 154 rows, 525 contracts),
 *   merged by `existing_registry_id` so no protocol appears twice;
 * - an eth_getCode re-check of every EVM address in this file, run on
 *   2026-10-31 against the public RPCs (Elysium testnet
 *   testnet-rpc.elysium.kinetiq.xyz, HyperEVM rpc.hyperliquid[-testnet].xyz/evm)
 *   and, for Elysium mainnet 99901, the read-only third-party relay
 *   rpc-live.elysp.com (the only keyless 99901 endpoint; Elyia never sends
 *   transactions through it).
 *
 * Only contracts the census marked verified AND that returned bytecode in the
 * re-check are listed (`contractInfo[].codeBytes`). Bytecode proves a
 * contract exists, not who owns it: `labelSource` says where each label
 * came from. Rows can still be edited by hand; keep `contracts` and
 * `contractInfo` in step (the validator checks both).
 *
 * `executable` is true only where an Elyia engine adapter exists
 * (apps/api/src/engine/registry.ts, 2026-10-31); `adapter` carries the
 * census' verified selectors and simulations for the rest.
 *
 * Hand edits of 2026-11-01: the `hyperswap-v3` row (HyperEVM testnet +
 * mainnet, every address re-checked by eth_getCode that day) and `signal`
 * executable (the engine's launch-router buys), so the executable rows equal
 * the engine adapters' protocol ids (the API test pins it).
 */
